    static func attaching(_ key: String, to original: SongDocument) -> SongDocument {
        guard let score = scores[key] else { preconditionFailure("Missing score: \(key)") }
        var song = original
        let serial = (scores.keys.sorted().firstIndex(of: key) ?? 0) + 1
        func id(_ value: Int) -> UUID {
            UUID(uuidString: String(format: "10000000-0000-0000-0000-%012d", serial * 10_000 + value))!
        }
        func beat(_ ticks: Int) -> Beat { try! Beat(Int64(ticks), 480) }
        let triples = score.noteData.split(separator: " ").map { entry -> [Int] in
            let values = entry.split(separator: ",").compactMap { Int($0) }
            precondition(values.count == 3 && (0...127).contains(values[0]) && values[1] >= 0 && values[2] > 0)
            return values
        }
        precondition(!triples.isEmpty)
        let measureTicks = score.meterNumerator * 480 * 4 / score.meterDenominator
        let endTick = triples.map { $0[1] + $0[2] }.max()!
        let measureCount = (endTick + measureTicks - 1) / measureTicks
        let partID = id(1)
        song.music.parts = [.init(id: partID, name: "旋律", clef: .suggested(forPitches: triples.map { $0[0] }))]
        song.music.meters = [.init(numerator: score.meterNumerator, denominator: score.meterDenominator)]
        song.music.measures = (0..<measureCount).map { index in
            Measure(id: id(100 + index), number: String(index + 1),
                    range: .init(start: beat(index * measureTicks), end: beat((index + 1) * measureTicks)))
        }
        song.music.events = triples.enumerated().map { index, values in
            MusicalEvent(id: id(1_000 + index), onset: beat(values[1]), duration: beat(values[2]),
                         measureID: song.music.measures[values[1] / measureTicks].id,
                         content: .note(.init(pitch: values[0])), partID: partID)
        }
        song.music.spans = [.init(id: id(9_000), kind: .section, title: "資料に基づく旋律",
                                  range: .init(start: .zero, end: beat(endTick)),
                                  eventIDs: song.music.events.map(\.id))]
        if song.phrases.count == 1 {
            song.phrases[0].timeRange = .init(start: .zero, end: beat(endTick))
            song.phrases[0].musicalEventIDs = song.music.events.map(\.id)
        }
        song.metadata.notes = song.metadata.notes
            .replacingOccurrences(of: "音符は未入力。", with: "")
            + " 旋律資料: \(score.sourceURL)。単旋律の音高と長さを入力。歌詞の音節と音符は未校訂です。"
        return song
    }
